      D2: schemaNum("D\u2082", "dynamics", "\u2014", 0.2, 2),
      mu: schemaNum("\u7C98\u5EA6 \u03BC", "dynamics", "\u2014", 1e-3, 1),
      rho: schemaNum("\u03C1", "dynamics", "\u2014", 0.2, 5)
